  } catch (e) {
    await logAudit({
      run_id: ctx.runId ?? null,
      agent_key: ctx.agentKey,
      model,
      prompt_preview: prompt.slice(0, 240),
      prompt_tokens: Math.ceil(prompt.length / 4),
